-- ======================================================================
-- Projet Congo Shop : création de la base et chargement des données (fictives)
-- Exécuter ce script en entier. Il recrée la base congo_shop à chaque lancement.
-- Les tables sont créées SANS contrainte : c'est volontaire. Les données brutes
-- contiennent des défauts à repérer et à corriger avant d'ajouter les contraintes.
-- ======================================================================
DROP DATABASE IF EXISTS congo_shop;
CREATE DATABASE congo_shop CHARACTER SET utf8mb4;
USE congo_shop;
SET NAMES utf8mb4;

CREATE TABLE villes (ville VARCHAR(50), province VARCHAR(50));
CREATE TABLE categories (id INT, nom VARCHAR(50));
CREATE TABLE produits (id INT, nom VARCHAR(100), categorie_id INT, prix DECIMAL(10,2));
CREATE TABLE clients (id INT, prenom VARCHAR(50), ville VARCHAR(50), telephone VARCHAR(20), date_inscription DATE);
CREATE TABLE commandes (id INT, client_id INT, date_commande DATE, statut VARCHAR(20));
CREATE TABLE lignes_commande (id INT, commande_id INT, produit_id INT, quantite INT, prix_unitaire DECIMAL(10,2));
CREATE TABLE livraisons (id INT, commande_id INT, transporteur VARCHAR(50), date_expedition DATE, date_livraison DATE, statut VARCHAR(20));

-- villes : 8 lignes

-- categories : 5 lignes

-- produits : 40 lignes

-- clients : 1530 lignes

-- commandes : 8810 lignes

-- lignes_commande : 17840 lignes

-- livraisons : 7753 lignes

-- Contrôles à lancer après le chargement
SELECT 'villes' AS table_nom, COUNT(*) AS nb FROM villes
UNION ALL SELECT 'categories', COUNT(*) FROM categories
UNION ALL SELECT 'produits', COUNT(*) FROM produits
UNION ALL SELECT 'clients', COUNT(*) FROM clients
UNION ALL SELECT 'commandes', COUNT(*) FROM commandes
UNION ALL SELECT 'lignes_commande', COUNT(*) FROM lignes_commande
UNION ALL SELECT 'livraisons', COUNT(*) FROM livraisons;
SELECT SUM(quantite * prix_unitaire) AS total_lignes FROM lignes_commande;
